export function calculateROI({
  revenue,
  margin,
  shifts,
  unplannedDowntime,
  downtimeReduction,
  productivityGain,
  manualWorkers,
  manualHours,
  hourlyRate,
  implCost,
  subscription,
}) {
  const hoursPerDay = shifts * 8;
  const revenuePerHour = (revenue * (margin / 100)) / (hoursPerDay * 30);

  const savingsDowntime =
    revenuePerHour * unplannedDowntime * (downtimeReduction / 100) * 30;

  const savingsProductivity =
    revenue * (margin / 100) * (productivityGain / 100);

  const savingsFOT = manualWorkers * manualHours * hourlyRate * 22;

  const totalSavings = savingsDowntime + savingsProductivity + savingsFOT;
  const netMonthly = totalSavings - subscription;
  const payback = netMonthly > 0 ? implCost / netMonthly : null;

  const roi12 =
    ((netMonthly * 12 - implCost) / (implCost + subscription * 12)) * 100;

  const savings3yr = netMonthly * 36 - implCost;

  return {
    revenuePerHour,
    savingsDowntime,
    savingsProductivity,
    savingsFOT,
    totalSavings,
    netMonthly,
    payback,
    roi12,
    savings3yr,
  };
}

