const STORAGE_KEY = "roi_saved_calculations";

export function getSavedCalculations() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];

    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    console.error("Ошибка чтения saved calculations:", error);
    return [];
  }
}

export function saveAllCalculations(calculations) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(calculations));
    return true;
  } catch (error) {
    console.error("Ошибка сохранения calculations:", error);
    return false;
  }
}

export function saveCalculation(calculation) {
  const existing = getSavedCalculations();
  const updated = [calculation, ...existing];
  return saveAllCalculations(updated);
}

export function deleteCalculation(id) {
  const existing = getSavedCalculations();
  const updated = existing.filter((item) => item.id !== id);
  return saveAllCalculations(updated);
